{"category":"item_linking","diagnosis_code":"MISSING_PAIRED_ITEM","faulty_node":"Pair Records 23","root_cause":"The Code node creates one output per input item but omits pairedItem metadata needed to preserve item linking.","patch":[{"op":"replace","path":"/nodes/1/parameters/jsCode","value":"const rows = $input.all();
return rows.map((row, index) => ({
  json: row.json,
  pairedItem: { item: index },
}));"}],"needs_human_review":false}

{"category":"code_node","diagnosis_code":"MISSING_PAIRED_ITEM","faulty_node":"Preserve Pairing 24","root_cause":"The Code node transforms items one-to-one but omits pairedItem metadata, so downstream item linking is lost.","patch":[{"op":"replace","path":"/nodes/1/parameters/jsCode","value":"const rows = $input.all();
return rows.map((row, index) => ({
  json: { ...row.json, normalized: true },
  pairedItem: { item: index },
}));"}],"needs_human_review":false}
